mapper.update:
UPDATE shipping_mark_import
SET status = #{status}, updated_by = #{updatedBy}, updator = #{updator},
    updated_at = #{updatedAt}, processed_at = #{processedAt}
WHERE id = #{id}

mapper.select:
SELECT  FROM shipping_mark_import WHERE 1 = 1 
ORDER BY created_at DESC, id DESC
LIMIT #{pageSize} OFFSET #{offset}
